  c('RES-L12', L, 'Bộ lọc', 'Lọc Thời hạn "Kỳ đang diễn ra" chỉ trả kỳ chưa kết thúc', 'Chức năng', 'Cao', '1. Chọn Thời hạn = Kỳ đang diễn ra', 'Mọi dòng có hạn nộp còn hiệu lực ("Còn n ngày"); không dòng nào "Đã kết thúc"; tổng khớp API phase=active');
  c('RES-L13', L, 'Bộ lọc', 'Lọc Thời hạn "Kỳ đã kết thúc" chỉ trả kỳ đã kết thúc', 'Chức năng', 'Cao', '1. Chọn Thời hạn = Kỳ đã kết thúc', 'Mọi dòng có Hạn nộp hiển thị "Đã kết thúc"; trạng thái chỉ là Đã gửi hoặc Chưa gửi; tổng khớp API phase=closed');
