  c('RES-L16', L, 'Tab trạng thái', 'Thời hạn Kỳ đã kết thúc: dải tab chỉ có Tất cả, Đã gửi, Chưa gửi', 'Chức năng', 'Trung bình', '1. Chọn Thời hạn = Kỳ đã kết thúc', 'Chỉ có tab Tất cả, Đã gửi, Chưa gửi (BR-5)');
