  const st = [['L18', 'Chưa thực hiện'], ['L19', 'Đang chấm điểm'], ['L20', 'Chờ duyệt'], ['L21', 'Bị từ chối'], ['L22', 'Đã phê duyệt'], ['L23', 'Đã gửi'], ['L24', 'Chờ mở khóa'], ['L25', 'Chưa gửi']];
  for (const [k, s] of st) c('RES-' + k, L, 'Tab trạng thái', `Chọn tab "${s}" chỉ hiển thị kết quả ở trạng thái ${s}`, 'Chức năng', 'Trung bình', `${GO}\n3. Chọn tab "${s}"`, `Mọi dòng có chip Trạng thái = ${s}; tổng bản ghi = số dòng khớp API filter status`, k === 'L20' || k === 'L21' ? 'Cần dữ liệu ở trạng thái này (tạo bằng kỳ thử); nếu chưa có dữ liệu, tab hiển thị rỗng' : '');
