  c('RES-L80', L, 'Xem danh sách', 'Điểm xếp hạng (%) bằng tổng điểm chia tổng điểm tối đa, làm tròn 2 chữ số thập phân', 'Nghiệp vụ', 'Trung bình', '1. [API] Lấy các dòng có score và maxScore\n2. Tính score*100/maxScore', 'rankingPercent = ROUND(score/maxScore*100, 2) cho mọi dòng Đã gửi/Chờ mở khóa (BR-10)');
  c('RES-L81', L, 'Xem danh sách', 'Mức xếp loại là mức có Từ ≤ Điểm xếp hạng < Đến dưới, điểm đúng bằng mốc thuộc mức trên, mức cuối gồm cả 100%', 'Nghiệp vụ', 'Cao', '1. [API] Lấy các dòng Đã gửi\n2. Đối chiếu levelCode với thang gắn kỳ (vd TXL-001: 0-40 Yếu, 40-60 Trung bình, 60-80 Khá, 80-90 Tốt, 90-100 Xuất sắc)', 'Điểm 40% → Trung bình (không phải Yếu); 100% → Xuất sắc (BR-10)', 'Cần dữ liệu có điểm đúng mốc 40/60/80/90/100%; dùng kỳ thử chấm đạt đúng mốc');
  c('RES-L82', L, 'Xem danh sách', 'Thứ tự mặc định của danh sách theo quy tắc ưu tiên xử lý/mới nhất trước', 'Nghiệp vụ', 'Thấp', '1. Mở danh sách\n2. Đối chiếu thứ tự các dòng', 'Thứ tự ổn định và theo quy tắc đã định', 'Khảo sát: UI gửi sort=-createdOnDate nhưng API trả theo thứ tự ưu tiên riêng (sort bị bỏ qua; sort tham số lạ vẫn 200). ' + BA);
  c('RES-L83', L, 'Xem danh sách', 'Mở trực tiếp URL có tham số loại kỳ (campaignType=AdHoc) hiển thị đúng loại kỳ', 'Chức năng', 'Thấp', '1. Mở URL …/assessment-results?campaignType=AdHoc&phase=all', 'Nút Đột xuất được chọn; danh sách là kỳ đột xuất');
  c('RES-L84', L, 'Xem danh sách', 'Tải lại trang (F5) giữ nguyên loại kỳ, từ khóa và bộ lọc trên URL', 'Chức năng', 'Thấp', '1. Chọn Đột xuất, nhập từ khóa\n2. F5', 'Vẫn ở Đột xuất với từ khóa cũ, cùng kết quả');

  // ===================== RES-V  XEM CHI TIẾT CHỈ SỐ / XUẤT EXCEL CHI TIẾT (UC1.7, UI-1.2.1; UC_1409 dòng 200-201) =====================
  c('RES-V01', V, 'Xem chi tiết', 'Trang chi tiết hiển thị tên kỳ, chip trạng thái, đơn vị và hạn nộp', 'Chức năng', 'Cao', GO + '\n3. Bấm "Xem chi tiết" một dòng', 'Tiêu đề = tên kỳ kèm chip trạng thái; dòng phụ gồm tên đơn vị, Hạn nộp (dd/mm/yyyy) và "Còn n ngày" (UC_1409 dòng 200)');
  c('RES-V02', V, 'Xem chi tiết', 'Khối Thông tin chung hiển thị Đơn vị, Phân loại, Bộ chỉ số áp dụng, Thời gian thực hiện', 'Chức năng', 'Cao', '1. Mở chi tiết một kết quả', 'Đủ 4 ô, đúng dữ liệu kỳ; Thời gian thực hiện dạng "từ ngày – đến ngày"; ô chỉ xem (UI-1.2.1)', 'Khảo sát: không có dòng phụ "số ngày còn lại" dưới Thời gian thực hiện (số ngày còn lại nằm dưới tiêu đề)');
  c('RES-V03', V, 'Xem chi tiết', 'Các thẻ tổng hợp Tiến độ chấm, Điểm tạm tính, Minh chứng hiển thị đúng số liệu', 'Chức năng', 'Cao', '1. Mở chi tiết kết quả đã chấm một phần', 'Tiến độ chấm "x / y"; Điểm tạm tính "a / b" kèm "Đạt n% điểm tối đa"; Minh chứng "k / y chỉ số" và số tệp; khớp dữ liệu API');
  c('RES-V04', V, 'Xem chi tiết', 'Mỗi chỉ số hiển thị mã, tên, điểm tối đa và trọng số', 'Chức năng', 'Cao', '1. Mở chi tiết, xem một nhóm chỉ số', 'Dòng chỉ số có Mã, Tên, "Điểm tối đa: n", "Trọng số: m" (nếu ≠1), đúng với bộ chỉ số của kỳ');
  c('RES-V05', V, 'Xem chi tiết', 'Mỗi nhóm hiển thị số chỉ số đã chấm "x/y đã chấm" và Điểm nhóm "a / b"', 'Nghiệp vụ', 'Trung bình', '1. Mở chi tiết, xem tiêu đề nhóm', 'Nhóm có chip "x/y đã chấm" và "Điểm nhóm: a / b"; a = tổng điểm kết quả chỉ số trong nhóm, b = tổng điểm tối đa (BR-2)');
  c('RES-V06', V, 'Xem chi tiết', 'Cây Trụ cột → Nhóm chỉ số → Chỉ số cha/con thụt cấp, dòng cha hiển thị điểm kết quả/điểm tối đa', 'Chức năng', 'Cao', '1. Mở chi tiết kết quả có bộ chỉ số nhiều cấp (kỳ thử dùng bộ MBCS_QC01: 100 chỉ số con, 20 chỉ số cha)', 'Có dòng Trụ cột, Nhóm, Chỉ số cha với mũi tên đóng/mở, cấp dưới thụt vào; dòng cha hiển thị "250 / 300" (UI-1.2.1)', 'Khảo sát: UI chỉ hiển thị Nhóm chỉ số rồi danh sách chỉ số phẳng (không dòng Trụ cột, không chỉ số cha; API có pillars/parentId/isLeaf) → nghi lỗi thiếu chức năng');
  c('RES-V07', V, 'Xem chi tiết', 'Cột Điểm của chỉ số hiển thị dạng (điểm tối thiểu - điểm tối đa)', 'Chức năng', 'Trung bình', '1. Mở chi tiết, xem cột điểm', 'Hiển thị "(50-100)": tối thiểu là ngưỡng Đạt, tối đa là mức chặn (UI-1.2.1)', 'Khảo sát: chỉ hiển thị "Điểm tối đa: n" dưới tên chỉ số, không hiển thị điểm tối thiểu → lệch SRS');
  c('RES-V08', V, 'Xem chi tiết', 'Cột Đánh giá hiển thị Đạt (xanh) hoặc Chưa đạt (đỏ nhạt) theo điểm kết quả và điểm tối thiểu', 'Nghiệp vụ', 'Cao', '1. Mở chi tiết kết quả đã chấm', 'Chip Đạt khi Điểm kết quả ≥ điểm tối thiểu, ngược lại Chưa đạt; chỉ số chưa chấm "-" (BR-10)', 'Khảo sát: giao diện không có cột Đánh giá và cột Điểm kết quả (API có isPassed/resultScore) → nghi lỗi thiếu chức năng');
  c('RES-V09', V, 'Xem chi tiết', 'Điểm kết quả của từng chỉ số bằng min(Điểm chấm × Trọng số, Điểm tối đa)', 'Nghiệp vụ', 'Cao', '1. Mở chi tiết chỉ số trọng số 2 đã chấm 3', 'Điểm kết quả 6 (3×2); không vượt điểm tối đa (BR-2)', 'Khảo sát: chi tiết chỉ hiển thị Điểm chấm "x / tối đa", chưa có cột Điểm kết quả; kiểm chứng qua API resultScore');
  man('RES-V10', V, 'Xem chi tiết', 'Chỉ số Không tính điểm hiển thị "-" ở Điểm chấm và Điểm kết quả', 'Nghiệp vụ', 'Trung bình', '1. Mở chi tiết kết quả có chỉ số Không tính điểm', 'Hai ô hiển thị "-", ô không nhập được (BR-3)', 'hệ thống không có sẵn bộ chỉ số có chỉ số Không tính điểm để kiểm chứng');
  c('RES-V11', V, 'Xem chi tiết', 'Điểm nhóm bằng tổng điểm kết quả các chỉ số trong nhóm; Điểm tạm tính bằng tổng các nhóm', 'Nghiệp vụ', 'Cao', '1. [API] GET chi tiết\n2. Cộng resultScore các chỉ số theo nhóm/tổng', 'groups[].score = Σ resultScore; score tổng = Σ nhóm; maxScore = Σ điểm tối đa chỉ số con tính điểm (BR-2, BR-12)');
  c('RES-V12', V, 'Xem chi tiết', 'Điểm trên chi tiết trùng với điểm và tiến độ trên danh sách', 'Nghiệp vụ', 'Trung bình', '1. Ghi Tiến độ chấm, Điểm ở danh sách\n2. Mở chi tiết', 'Tiến độ chấm và Điểm tạm tính ở chi tiết bằng danh sách');
  c('RES-V13', V, 'Xem chi tiết', 'Kỳ đã kết thúc: trang chi tiết chỉ xem, không có ô nhập điểm, không nút Lưu nháp/Trình duyệt', 'Nghiệp vụ', 'Cao', '1. Mở chi tiết một kết quả Chưa gửi/Đã gửi của kỳ đã kết thúc', 'Không có ô nhập; không có nút Chỉnh sửa/Lưu nháp/Trình duyệt; hiển thị "Đã kết thúc"');
  c('RES-V14', V, 'Xem chi tiết', 'Lãnh đạo xem chi tiết ở chế độ chỉ xem (không có ô nhập, không nút chấm)', 'Bảo mật', 'Cao', '1. Đăng nhập Lãnh đạo đơn vị\n2. Mở chi tiết kết quả Đang chấm điểm', 'Không có ô nhập điểm, giải trình, nút Đính kèm, Lưu nháp, Trình duyệt');
  c('RES-V15', V, 'Xem chi tiết', 'Tab Lịch sử liệt kê các hành động xử lý theo thời gian kèm người thực hiện', 'Chức năng', 'Trung bình', '1. Mở chi tiết\n2. Bấm tab Lịch sử', 'Mỗi dòng: hành động, trạng thái trước/sau, người, thời gian; mới nhất trước; số đếm trên tab = số dòng');
  c('RES-V16', V, 'Xem chi tiết', 'Nút quay lại ở chi tiết về danh sách giữ nguyên bộ lọc trước đó', 'Chức năng', 'Thấp', '1. Ở danh sách chọn Đột xuất, tab Đã gửi\n2. Mở chi tiết\n3. Bấm nút quay lại', 'Về danh sách vẫn ở Đột xuất, tab Đã gửi');
  c('RES-V17', V, 'Xem chi tiết', 'Mở chi tiết với id không tồn tại hiển thị trang 404 và không lộ lỗi nội bộ', 'Validate', 'Cao', '1. Mở URL chi tiết với id GUID lạ\n2. [API] GET /dti/assessment-results/<id lạ>', 'API 404 "Không tìm thấy kết quả tự đánh giá"; giao diện trang "404 Không tìm thấy nội dung", không trắng trang, không stacktrace');
  c('RES-V18', V, 'Xem chi tiết', 'Mở chi tiết với id sai định dạng (không phải GUID) không gây lỗi 500', 'Validate', 'Trung bình', '1. [API] GET /dti/assessment-results/abc\n2. GET với chuỗi SQL', 'HTTP 404/400 không nội dung lỗi nội bộ; không 500');
  c('RES-V19', V, 'Xem chi tiết', 'Tìm chỉ số theo mã hoặc tên ở trang chi tiết', 'Chức năng', 'Trung bình', '1. Nhập mã chỉ số, rồi một phần tên vào ô "Tìm mã hoặc tên chỉ số"', 'Chỉ còn các chỉ số khớp (không phân biệt hoa/thường); nhóm không còn chỉ số thì ẩn');
  c('RES-V20', V, 'Xem chi tiết', 'Xuất Excel chi tiết tải được file chấm điểm .xlsx', 'Chức năng', 'Cao', '1. Mở chi tiết\n2. Bấm "Xuất Excel"', 'Tải về file cham-diem-<tên kỳ>.xlsx mở được (UC_1409 dòng 201)', 'SRS: "Chi tiết kết quả chưa có Xuất Excel (làm trong tương lai)" nhưng thực tế đã có; UC_1409 dòng 201 FE/BE "Chưa làm" → ' + BA);
  c('RES-V21', V, 'Xem chi tiết', 'File Excel chi tiết chứa đủ các chỉ số, điểm chấm, điểm kết quả và giải trình', 'Nghiệp vụ', 'Trung bình', '1. Chấm vài chỉ số kèm giải trình\n2. Xuất Excel chi tiết, mở file', 'Mỗi chỉ số một dòng: mã, tên, điểm tối đa, trọng số, điểm chấm, điểm kết quả, giải trình; tổng điểm khớp trang');
  c('RES-V22', V, 'Xem chi tiết', '[API] Xuất Excel chi tiết với id không tồn tại trả 404', 'Validate', 'Trung bình', '1. [API] GET /dti/assessment-results/<id lạ>/export', 'HTTP 404 "Không tìm thấy kết quả tự đánh giá"; không trả file');
  c('RES-V23', V, 'Xem chi tiết', 'Số chỉ số trong tab "Chấm điểm (x/y)" bằng số chỉ số cần chấm', 'Nghiệp vụ', 'Trung bình', '1. Mở chi tiết, đọc "Chấm điểm (x/y)"', 'x = số chỉ số đã có điểm, y = số chỉ số cần chấm (chỉ chỉ số con tính điểm)');
  c('RES-V24', V, 'Xem chi tiết', 'Lọc chỉ số theo Nhóm chỉ số ở trang chi tiết', 'Chức năng', 'Thấp', '1. Chọn một nhóm ở ô "Nhóm chỉ số"', 'Chỉ còn nhóm đã chọn; bỏ chọn thì hiện tất cả');

