  c('RES-S03', S, 'Lưu nháp', 'Lưu nháp lần đầu chuyển Chưa thực hiện sang Đang chấm điểm', 'Nghiệp vụ', 'Cao', '1. Kết quả Chưa thực hiện\n2. Nhập điểm, Lưu nháp', 'Trạng thái = Đang chấm điểm (BR-6)');
  c('RES-S04', S, 'Lưu nháp', 'Lưu nháp các lần sau giữ nguyên trạng thái Đang chấm điểm', 'Nghiệp vụ', 'Trung bình', '1. Kết quả Đang chấm điểm\n2. Đổi điểm, Lưu nháp lần nữa', 'Trạng thái vẫn Đang chấm điểm (BR-6)');
  c('RES-S05', S, 'Lưu nháp', 'Lịch sử xử lý ghi hành động Lưu nháp sau mỗi lần lưu', 'Nghiệp vụ', 'Trung bình', '1. Lưu nháp 2 lần\n2. Mở tab Lịch sử', 'Có hành động "Lưu nháp" cho các lần lưu (post-condition UC1.2)', 'Khảo sát: chỉ có "StartedScoring" cho lần đầu; các lần Lưu nháp sau không ghi lịch sử → nghi lỗi. ' + BA);
  c('RES-S06', S, 'Lưu nháp', 'Lưu nháp không yêu cầu đủ điểm (chỉ chấm một phần chỉ số vẫn lưu được)', 'Nghiệp vụ', 'Cao', '1. Kết quả nhiều chỉ số: chấm 1 chỉ số, bỏ trống các chỉ số khác\n2. Lưu nháp', 'Lưu thành công; tiến độ chấm 1/n (BR-6)', 'Cần kỳ thử dùng bộ chỉ số nhiều chỉ số (MBCS_QC01)');
  c('RES-S07', S, 'Lưu nháp', 'Lưu khi mọi ô điểm đều trống vẫn lưu được ô trống, không bị chặn', 'Nghiệp vụ', 'Trung bình', '1. Kết quả Chưa thực hiện, không nhập điểm\n2. Bấm Lưu nháp', 'Lưu thành công, các ô điểm vẫn trống (BR-11: Lưu nháp lưu ô trống)', 'Khảo sát: API 400 "Vui lòng nhập điểm cho ít nhất 1 chỉ số" khi không có điểm nào → lệch BR-6/BR-11. ' + BA);
  c('RES-S08', S, 'Lưu nháp', 'Ô Điểm chấm để trống không bị hiểu là 0', 'Nghiệp vụ', 'Cao', '1. Chấm chỉ số A=4, để trống chỉ số B\n2. Lưu nháp, tải lại', 'Chỉ số B vẫn trống ("-"), không thành 0; tiến độ đếm 1 chỉ số (BR-11)', 'Cần kỳ thử bộ chỉ số nhiều chỉ số');
  c('RES-S09', S, 'Lưu nháp', 'Xóa điểm đã lưu về trống rồi Lưu nháp thì chỉ số trở lại chưa chấm', 'Nghiệp vụ', 'Trung bình', '1. Chỉ số A, B đã có điểm\n2. Xóa điểm A, Lưu nháp', 'A trở lại trống, không thành 0; tiến độ giảm 1 (BR-11)', 'Khảo sát: API không có cách xóa điểm (score=null bị bỏ qua / báo lỗi) → nghi lỗi. ' + BA);
  // --- Điểm: biên và định dạng ---
  c('RES-S10', S, 'Nhập điểm', 'Nhập điểm âm báo "Điểm phải lớn hơn hoặc bằng 0" dưới ô và không cho lưu', 'Validate', 'Cao', '1. Gõ -1 vào ô Điểm chấm\n2. Bấm Lưu nháp', 'Hiển thị "Điểm phải lớn hơn hoặc bằng 0" (MSG-057) dưới ô; không lưu (EF1)', 'Khảo sát: ô tự đổi -1 thành 0.0 không thông báo, vẫn lưu (UI kẹp theo min của InputNumber) → nghi lỗi');
  c('RES-S11', S, 'Nhập điểm', 'Nhập điểm có phần thập phân báo "Điểm phải là số nguyên" dưới ô và không cho lưu', 'Validate', 'Cao', '1. Gõ 2.5 vào ô Điểm chấm\n2. Bấm Lưu nháp', 'Hiển thị "Điểm phải là số nguyên" (MSG-083) dưới ô; không lưu (EF2)', 'Khảo sát: ô nhận 2.5 (step 0.5); khi Lưu nháp API 400 "Điểm chỉ số X phải là số nguyên" hiện toast, không có thông báo dưới ô → lệch SRS');
  c('RES-S12', S, 'Nhập điểm', '[API] Điểm âm bị từ chối HTTP 400 có thông báo, dữ liệu cũ giữ nguyên', 'Validate', 'Cao', '1. [API] PUT /dti/assessment-results/{id}/scores với score -1', 'HTTP 400 "Điểm chỉ số <mã> phải lớn hơn hoặc bằng 0"; điểm đã lưu trước đó không đổi');
