  c('RES-S17', S, 'Nhập điểm', 'Điểm kết quả = Điểm chấm × Trọng số khi chưa vượt điểm tối đa', 'Nghiệp vụ', 'Cao', '1. Chỉ số tối đa 8, trọng số 2: nhập 3', 'Điểm kết quả = 6 (BR-2)');
  c('RES-S18', S, 'Nhập điểm', 'Điểm kết quả bị chặn ở điểm tối đa khi Điểm chấm × Trọng số vượt tối đa', 'Nghiệp vụ', 'Cao', '1. Chỉ số tối đa 8, trọng số 2: nhập 5', 'Tính được 10 nhưng điểm kết quả = 8 (ví dụ BR-2: tối đa 20, trọng số 3, chấm 10 → 20)', 'Dùng bộ BA-TEST-SET (tối đa 8, trọng số 2)');
  c('RES-S19', S, 'Nhập điểm', 'Điểm kết quả, điểm nhóm và tổng điểm tạm tính cập nhật ngay khi nhập (chưa cần lưu)', 'Chức năng', 'Cao', '1. Nhập điểm vào một chỉ số', 'Điểm nhóm, thẻ Điểm tạm tính, % điểm tối đa đổi ngay; chưa gọi API lưu (BR-2)');
