  c('RES-S21', S, 'Nhập điểm', 'Cột Đánh giá là Đạt khi Điểm kết quả ≥ điểm tối thiểu và Chưa đạt khi nhỏ hơn', 'Nghiệp vụ', 'Cao', '1. Chỉ số có điểm tối thiểu 5: nhập điểm cho kết quả 4 rồi 6', 'Kết quả 4 → Chưa đạt; kết quả 6 → Đạt (BR-10)', 'Khảo sát: chưa có cột Đánh giá trên UI; API isPassed. Dữ liệu seed có minScore=0 nên cần bộ chỉ số có minScore>0');
  c('RES-S22', S, 'Nhập điểm', 'Điểm kết quả đúng bằng điểm tối thiểu thì Đạt (biên)', 'Nghiệp vụ', 'Trung bình', '1. Chỉ số có điểm tối thiểu 5, trọng số 1: nhập 5', 'Đánh giá = Đạt (BR-10: ≥ điểm tối thiểu)');
  c('RES-S23', S, 'Nhập điểm', 'Điểm tối thiểu không phải cận dưới của ô nhập: nhập điểm nhỏ hơn điểm tối thiểu vẫn lưu được', 'Nghiệp vụ', 'Cao', '1. Chỉ số điểm tối thiểu 5: nhập 2\n2. Lưu nháp', 'Lưu thành công, Đánh giá Chưa đạt (BR-10)', 'Khảo sát: UI đặt min=minScore cho ô nhập và Trình duyệt báo "ngoài khoảng cho phép" → mâu thuẫn BR-10. ' + BA);
