  c('RES-N11', TB, 'Thông báo yêu cầu tự đánh giá', 'Tài khoản thuộc đơn vị không được phân công kỳ không nhận thông báo', 'Bảo mật', 'Cao', '1. Phê duyệt kỳ thử chỉ gán đơn vị QC_BO\n2. Kiểm thông báo của Cán bộ địa phương và Lãnh đạo địa phương', 'Không có thông báo của kỳ đó ở tài khoản đơn vị khác', 'Khảo sát: cbdp/ldp không nhận; nhưng canbo/ldd (phạm vi toàn hệ thống) nhận cả kỳ của đơn vị khác. ' + BA);
  c('RES-N12', TB, 'Thông báo yêu cầu tự đánh giá', 'Mỗi người chỉ nhận một thông báo cho mỗi kỳ được phân công (không trùng)', 'Nghiệp vụ', 'Trung bình', '1. Phê duyệt kỳ thử\n2. Đếm thông báo chứa campaignId của kỳ ở từng tài khoản', 'Đúng 1 thông báo/tài khoản/kỳ');
