  c('RES-G09', L, 'Lỗi', '[API] Tham số filter không phải JSON hợp lệ trả 400 "Bộ lọc không hợp lệ"', 'Validate', 'Trung bình', '1. [API] GET /dti/assessment-results?filter={bad', 'HTTP 400 "Bộ lọc không hợp lệ", không 500');
  c('RES-G10', L, 'Lỗi', '[API] page=0, size=0, size âm được xử lý an toàn', 'Validate', 'Trung bình', '1. [API] GET page=0; size=0; size=-1', 'Trả 200 với page tối thiểu 1 và size mặc định/hợp lệ hoặc 400; không 500', 'Khảo sát: page=0→page 1; size=0 và size=-1 trả TOÀN BỘ bản ghi (size=118) → ' + BA);
